import sys,json,collections,statistics
sys.path.insert(0,'/tmp/an'); sys.path.insert(0,'/workspace')
from law import analyse
rows, listed, whole, parts = analyse()
ranks_missing=[]; ranks_pred=[]
for r in rows:
    answers=[a for _,a in r['items']]
    # rank of first case carrying each missing token
    for m in r['missing']:
        for i,a in enumerate(answers):
            if m in a:
                ranks_missing.append(i); break
        else:
            ranks_missing.append(None)
    for p in r['pred']:
        for i,a in enumerate(answers):
            if p in a:
                ranks_pred.append((i, r['correct'])); break
        else:
            ranks_pred.append((None, r['correct']))
def dist(vals):
