import json,glob,collections,sys,re
sys.path.insert(0,'/workspace'); sys.path.insert(0,'/tmp/an')
from benchmark.data.evaluators import extract_final_answer
RUN='/workspace/runs/bf9c69efaa50709642cd760ec49d71e2743b8c5b'
def parse(task,text):
    t=extract_final_answer(text or '')
    if task=='LawBench':
        t=t.strip()
        m=re.search(r"\[罪名\](.*?)(?:<eoa>|$)", t, re.S)
        if m: t=m.group(1).strip()
        elif "罪名:" in t: t=t.split("罪名:")[-1]
        t=re.sub(r"<eoa>.*","",t).strip()
        for sep in [";","；",",","，","、"]:
            if sep in t: return frozenset(p.strip() for p in t.split(sep) if p.strip())
        return frozenset([t] if t else [])
    if task=='Symptom2Disease':
        m=re.search(r"\[DIAGNOSIS\](.*?)\[/DIAGNOSIS\]", t, re.I|re.S)
        if m: t=m.group(1).strip()
        t=re.sub(r"\s+"," ",t.lower().strip()); return re.sub(r"[.!?]+$","",t)
    return frozenset(p.strip().lower() for p in t.strip().split('.') if p.strip())

def grams(s,n=3): 
    s=s.lower()
    return [s[i:i+n] for i in range(max(1,len(s)-n+1))]

class Criteria:
    def __init__(self, task):
        self.task=task
        mem=json.load(open(f'{RUN}/{task}/memory.json'))['examples']
        self.answers=[e['target'] for e in mem]
        self.counts=collections.Counter()
        for a in self.answers: self.counts.update(set(grams(a)))
        from tools.retrieval import listed_strings
        import tools.retrieval as R
        R.load_examples=lambda: mem
        whole,parts=R.listed_strings(mem)
        self.listed=set(whole)|set(parts)
        self.raw=[e.get('raw_question','') for e in mem]
    def c_ngram(self, ans, q):
        return sum(self.counts[g] for g in set(grams(ans)))
    def c_len(self, ans, q):
        return len(ans)
    def c_entries(self, ans, q):
        return len(ans)
    def c_qsim(self, ans, q):
        a=set(grams(ans,2)); b=set(grams(q,2))
        return len(a&b)/(len(a|b)+1e-9)
    def c_listed(self, ans, q):
        if not self.listed: return 0
        toks=re.split(r"[;；,，、]|\.", ans)
        toks=[t.strip() for t in toks if t.strip()]
        if not toks: return 0
        return sum(1 for t in toks if t in self.listed)/len(toks)
    def c_maxmem(self, ans, q):
        a=set(grams(ans))
        best=0
        for m in self.answers:
            b=set(grams(m))
            s=len(a&b)/(len(a|b)+1e-9)
            if s>best: best=s
        return best

def pairs(task):
    out=[]
    for f in sorted(glob.glob('/workspace/runs/*/results/samples.jsonl')):
        run=f.split('/')[3]
        byq=collections.defaultdict(list)
        for line in open(f):
            d=json.loads(line)
            if d.get('task')!=task: continue
            byq[d['example_index']].append(d)
        for i,v in byq.items():
            if len(v)==2 and v[0].get('prediction') is not None and v[1].get('prediction') is not None:
                out.append((run,i,v[0],v[1]))
    return out

def question_text(task, run, idx):
