def fully_written(self, answer: str) -> bool:
    """True when every entry of the answer is one the memory's own list writes.

    An answer the memory writes out in full cannot be improved on by deriving it again: a
    second derivation could at best write the same entries, and an answer the memory writes
    is the one the harness keeps anyway. So this is where the second derivation is left
    unmade, which on the frozen memories is 4 of every 5 LawBench answers and 9 of every 10
    Symptom2Disease answers, and never on USPTO, whose memory writes each answer once.
    """
    return bool(answer.strip()) and self.support(answer) >= 1.0

